// Normalise, then build the email. One node, because the two jobs share the
// same loop and splitting them buys nothing.
//
// The normalise half exists because PostgREST returns the whole result set as
// a single JSON array, and how n8n unwraps that has varied between versions:
// sometimes one item holding an array, sometimes one item per row. Rather than
// depend on which, flatten whatever turns up. An empty result — the normal
// case on most days — returns [] and nothing downstream runs.
const cfg = $('Config').first().json;
const base = String(cfg.webhookBase).replace(/\/+$/, '');
const product = cfg.productName;

const rows = [];
for (const item of $input.all()) {
  const j = item.json;
  if (Array.isArray(j)) rows.push(...j);
  else if (Array.isArray(j.data)) rows.push(...j.data);
  else if (j && j.token) rows.push(j);
}

return rows
  .filter((r) => r && r.token && r.email)
  .map((r) => {
    const link = (n) =>
      `${base}/rate?token=${encodeURIComponent(r.token)}&rating=${n}`;

    const stars = [1, 2, 3, 4, 5]
      .map(
        (n) =>
          `<a href="${link(n)}" style="display:inline-block;padding:10px 16px;margin:0 3px;border:1px solid #d7dae0;border-radius:8px;text-decoration:none;color:#1a1d23;font-size:18px;font-weight:600;">${n}</a>`
      )
      .join('');

    const html = `<!doctype html>\n<html><body style="margin:0;padding:24px;background:#f4f6f9;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#1a1d23;">\n  <div style="max-width:520px;margin:0 auto;background:#ffffff;border:1px solid #e4e7ec;border-radius:12px;padding:32px;">\n    <h1 style="margin:0 0 12px;font-size:20px;">How is ${product} working out?</h1>\n    <p style="margin:0 0 8px;font-size:15px;line-height:1.5;">You filled in the career survey a day ago &mdash; thanks for that.</p>\n    <p style="margin:0 0 24px;font-size:15px;line-height:1.5;">One click is all this needs: how would you rate the site so far?</p>\n    <div style="text-align:center;margin:0 0 8px;">${stars}</div>\n    <p style="margin:8px 0 24px;text-align:center;font-size:13px;color:#6b7280;">1 = poor &nbsp;&nbsp; 5 = excellent</p>\n    <p style="margin:0;font-size:13px;color:#6b7280;line-height:1.5;">There is a comment box on the next page if you want it, but the click on its own is enough.</p>\n  </div>\n</body></html>`;

    const text = [
      `How is ${product} working out?`,
      '',
      'You filled in the career survey a day ago - thanks for that.',
      'How would you rate the site so far? (1 = poor, 5 = excellent)',
      '',
      ...[1, 2, 3, 4, 5].map((n) => `${n}: ${link(n)}`),
    ].join('\n');

    return {
      json: {
        user_id: r.user_id,
        email: r.email,
        token: r.token,
        subject: `How is ${product} working out?`,
        html,
        text,
      },
    };
  });
